import{_ as i,o as e,c as a,a2 as t}from"./chunks/framework.BWuWLRhz.js";const k=JSON.parse('{"title":"Packaging & Distribution","description":"","frontmatter":{},"headers":[],"relativePath":"dev-guide/packaging.md","filePath":"dev-guide/packaging.md","lastUpdated":1790963768000}'),n={name:"dev-guide/packaging.md"};function l(o,s,r,p,d,h){return e(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="packaging-distribution" tabindex="-1">Packaging &amp; Distribution <a class="header-anchor" href="#packaging-distribution" aria-label="Permalink to &quot;Packaging &amp; Distribution&quot;">​</a></h1><p>This chapter details directory conventions for plugin assemblies, bundling third-party dependencies, embedding i18n JSON resources, and automated build deployment.</p><h2 id="_1-plugin-assembly-directory-structure" tabindex="-1">1. Plugin Assembly Directory Structure <a class="header-anchor" href="#_1-plugin-assembly-directory-structure" aria-label="Permalink to &quot;1. Plugin Assembly Directory Structure&quot;">​</a></h2><p>Lertaro recursively scans the <code>Plugins\\</code> folder located in the application root directory. To maintain clean isolation and avoid dependency conflicts across different plugins, place each plugin into its own dedicated subfolder:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Lertaro/</span></span>
<span class="line"><span>├── Lertaro.App.exe</span></span>
<span class="line"><span>├── Lertaro.PluginSdk.dll</span></span>
<span class="line"><span>└── Plugins/</span></span>
<span class="line"><span>    └── MyCustomPlugin/</span></span>
<span class="line"><span>        ├── Lertaro.Plugins.MyCustomPlugin.dll   (Main Plugin Assembly)</span></span>
<span class="line"><span>        ├── ThirdParty.Managed.dll              (Managed Third-Party Dependency)</span></span>
<span class="line"><span>        └── NativeLibrary.dll                   (Native C/C++ Dependency — placed FLAT)</span></span></code></pre></div><ul><li><strong>Automatic Dependency Probing</strong>: When Lertaro loads the primary DLL via <code>Assembly.LoadFrom</code>, the .NET runtime automatically probes the plugin&#39;s folder for adjacent dependencies without cross-contaminating other plugins.</li><li><strong>Native dependencies sit next to the DLL, not under <code>runtimes\\&lt;rid&gt;\\native</code></strong>: shipped plugin projects set <code>&lt;GenerateDependencyFile&gt;false&lt;/GenerateDependencyFile&gt;</code>, so no <code>.deps.json</code> is produced and the runtime has no deps graph to resolve an RID subfolder from. A native library therefore has to be discoverable in the application base directory — copy it flat. This is also why the two architectures are published as separate artifacts rather than one combined installer: only one architecture&#39;s native copy can occupy that flat load directory.</li><li><strong>Native File Toleration</strong>: When non-.NET native binaries (e.g. <code>e_sqlite3.dll</code>) are encountered by the assembly scan, the loader logs them at <code>Debug</code> level and moves on instead of raising a false-positive <code>Error</code>.</li></ul><h2 id="_2-automated-postbuild-copy-configuration" tabindex="-1">2. Automated PostBuild Copy Configuration <a class="header-anchor" href="#_2-automated-postbuild-copy-configuration" aria-label="Permalink to &quot;2. Automated PostBuild Copy Configuration&quot;">​</a></h2><p>Add a <code>PostBuild</code> MSBuild target to your plugin&#39;s <code>.csproj</code> to deploy the output into the Lertaro debug directories on every successful build. This is what the in-repo plugin projects actually do — note the <strong>flat</strong> destination and the <strong>second copy for the Service</strong>, which is what makes an alias or translation provider available to the indexer as well as to the UI:</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Target</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PostBuild&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> AfterTargets</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PostBuildEvent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Copy</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SourceFiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;$(TargetDir)$(TargetName).dll&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        DestinationFolder</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;..\\..\\App\\bin\\$(Configuration)\\net10.0-windows\\Plugins\\&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        SkipUnchangedFiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;true&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Copy</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SourceFiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;$(TargetDir)$(TargetName).dll&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        DestinationFolder</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;..\\..\\Service\\bin\\$(Configuration)\\net10.0-windows\\Plugins\\&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        SkipUnchangedFiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;true&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Target</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>Copy third-party managed or native dependencies to the same folder in a sibling <code>&lt;Copy&gt;</code> item if your plugin needs them at load time.</p><h2 id="_3-embedding-localization-resources" tabindex="-1">3. Embedding Localization Resources <a class="header-anchor" href="#_3-embedding-localization-resources" aria-label="Permalink to &quot;3. Embedding Localization Resources&quot;">​</a></h2><p>If your plugin implements the <a href="./sdk/ui-extensions.html"><code>ITranslationProvider</code></a> interface, embed your translation JSON files directly as <strong>Embedded Resources</strong> to prevent missing language files:</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ItemGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">EmbeddedResource</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Include</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Resources\\Translations\\**\\*.json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ItemGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>Organize files as <code>Resources/Translations/{culture}/{type}.json</code>, where <code>{type}</code> is the <code>typeName</code> you pass to <code>TranslationService.LoadEmbeddedTranslations(assembly, cultureKey, typeName)</code>. Every plugin in this repository uses the fixed file name <strong><code>Plugin.json</code></strong> (<code>Resources/Translations/zh-CN/Plugin.json</code>, <code>Resources/Translations/en-US/Plugin.json</code>, …) and passes <code>&quot;Plugin&quot;</code>; <code>App.json</code> is not a plugin convention — it exists only in CoreExtensions, which also supplies the host&#39;s own UI strings. The culture folders follow the app&#39;s seven locales, and a culture with no folder simply falls back to the caller&#39;s default text.</p><h2 id="_4-versioning-metadata" tabindex="-1">4. Versioning &amp; Metadata <a class="header-anchor" href="#_4-versioning-metadata" aria-label="Permalink to &quot;4. Versioning &amp; Metadata&quot;">​</a></h2><p>Define assembly version numbers and descriptions inside your <code>.csproj</code>:</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">PropertyGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;1.2.0&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">AssemblyVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;1.2.0.0&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">AssemblyVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">FileVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;1.2.0.0&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">FileVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;High-performance search source and context action extension plugin.&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">PropertyGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>This version and description string will be presented automatically inside the <strong>Settings → Plugins</strong> card.</p><h2 id="_5-release-build-architecture-artifacts" tabindex="-1">5. Release Build &amp; Architecture Artifacts <a class="header-anchor" href="#_5-release-build-architecture-artifacts" aria-label="Permalink to &quot;5. Release Build &amp; Architecture Artifacts&quot;">​</a></h2><p>Run <code>make.bat</code> from the repository root on Windows with the .NET SDK and the <a href="https://jrsoftware.org/isdl.php#v7" target="_blank" rel="noreferrer">64-bit edition of Inno Setup 7</a> installed. As it stands the script invokes its build routine <strong>once, for x64</strong>, and produces:</p><ul><li><code>Lertaro-Setup.exe</code> and <code>Lertaro-Portable.zip</code> in <code>dist/</code>.</li></ul><p>Its header comment describes two architectures (&quot;x64 publishes with no RID exactly as it always has; arm64 is a cross-publish&quot;) and its closing banner prints the arm64 paths, but no second <code>:build_arch</code> call sets <code>ARCH=x64</code>→<code>arm64</code>, so a local run does not create <code>Lertaro-Setup-arm64.exe</code> or <code>Lertaro-Portable-arm64.zip</code> — even though the release workflow hashes and uploads exactly those names. Keep that in mind before trusting the banner. The arm64 installer differs from the x64 one only in <code>ArchitecturesAllowed</code> (<code>arm64</code> vs <code>x64compatible</code>) plus <code>SetupArchitecture=x64</code> in <code>Installer/installer.iss</code>; the payload inside each is native to its architecture. Keep artifact names aligned with <code>make.bat</code>, <code>Installer/installer.iss</code>, and the release workflow&#39;s asset list.</p>`,22)])])}const g=i(n,[["render",l]]);export{k as __pageData,g as default};
